import {exercises as E,plans,illustration} from './exercises.js';
import {foods,week,targets,macros,scaledMeals,shoppingList,replaceMeal,optionalSnack,mealSlots} from './nutrition.js';
import {blank,remaining,pauseTimer,resumeTimer,weekNumber,nextSession,recommendation,makeSession,recordSet,advance,validateImport,openDB,readDB,saveDB} from './core.js';
let db,state=blank(),page='dashboard',energy='normal',selected='A',day=(new Date().getDay()+6)%7,query='',filter='Todos',phase=0,deload=false,notifyMinute='',audioCtx;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), fmt=n=>Math.round(n).toLocaleString('es-ES'), clock=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
const icon=(n)=>{const paths={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',train:'M6 7v10 M3 9v6 M18 7v10 M21 9v6 M6 12h12',library:'M4 4h6v16H4z M14 4h6v16h-6z',nutrition:'M7 3v7 M4 3v5a3 3 0 0 0 6 0V3 M7 10v11 M18 3v18 M18 3c-5 2-5 9 0 9',progress:'M3 3v18h18 M6 15l5-5 4 3 6-8',settings:'M4 7h16 M4 17h16 M9 4v6 M16 14v6'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.train}"/></svg>`};
const mark='<svg class="brandmark" viewBox="0 0 40 44" fill="none" aria-hidden="true"><path d="M20 2 36 9v15L20 41 4 24V9Z" stroke="currentColor" stroke-width="2"/><path d="m10 16 10 6 10-6M10 23l10 6 10-6" stroke="currentColor" stroke-width="3"/></svg>';
const btn=(label,action,cls='',attrs='')=>`<button class="${cls}" data-act="${action}" ${attrs}>${label}</button>`;
async function persist(){try{await saveDB(db,state)}catch(e){toast('No se pudo guardar. Exporta tus datos antes de cerrar.');console.error(e)}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',4500)}
function modal(title,html){$('#dialog').innerHTML=`<div class="dialogtop"><h2>${title}</h2>${btn('✕','close','ghost','aria-label="Cerrar"')}</div>${html}`;if(!$('#dialog').open)$('#dialog').showModal()}
const recent=()=>state.sessions.filter(s=>s.complete&&s.ended>=Date.now()-7*86400000);
function meals(d=day){return scaledMeals(d,state.profile,state.overrides)}
function title(k,t,extra=''){return `<div class="pagehead"><div><div class="eyebrow">${k}</div><h2>${t}</h2></div>${extra}</div>`}
function stat(k,v,n){return `<div class="stat"><div class="eyebrow">${k}</div><strong>${v}</strong><small>${n}</small></div>`}
function render(){const nav=[['dashboard','Inicio'],['train','Entrenar'],['library','Ejercicios'],['nutrition','Nutrición'],['progress','Progreso'],['settings','Ajustes']];$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">${mark}SEALGYM</div><div class="subbrand">EXECUTIVE TRAINING</div><nav class="nav" aria-label="Navegación principal">${nav.map(([p,n])=>btn(`${icon(p)}<span>${n}</span>`,'nav',page===p?'active':'',`data-page="${p}" ${page===p?'aria-current="page"':''}`)).join('')}</nav><div class="sidebarfoot"><span class="lime">● SISTEMA PERSONAL</span><br>DISCIPLINA. FUERZA. CONSTANCIA.<br><br>Datos guardados en este dispositivo<br>SEALGYM / V.01</div></aside><main class="content"><header class="topbar"><span class="eyebrow desktoplabel">TU CENTRO DE ENTRENAMIENTO</span><span class="mobilebrand">SEALGYM<span class="lime"> /</span></span><div class="row"><span class="online">${navigator.onLine?'LISTO PARA ENTRENAR':'MODO SIN CONEXIÓN'}</span><span class="avatar" aria-label="Perfil personal">SG</span></div></header>${({dashboard:dashboard,train:train,library:library,nutrition:nutrition,progress:progress,settings:settings}[page])()}<footer class="bottomnote"><span>CONSISTENCIA POR ENCIMA DE INTENSIDAD.</span><span>EXECUTIVE TRAINING © 2026</span></footer></main></div>`;tick()}
function dashboard(){let n=nextSession(state),w=weekNumber(state),done=recent().length,t=targets(state.profile);let m=meals();return `${title('OPERACIÓN: MEJOR VERSIÓN','Tu próxima misión empieza aquí.',`<span class="badge">SEMANA ${String(w).padStart(2,'0')} / 12</span>`)}<section class="hero"><div class="herotext"><span class="tag">▰ PROGRAMA DE FUERZA · 12 SEMANAS</span><h1>EXECUTIVE<br><span class="lime">TRAINING.</span></h1><p>Entrena con inteligencia.<br>Construye resultados.</p>${btn(state.active?'CONTINUAR ENTRENAMIENTO →':'EMPEZAR ENTRENAMIENTO →','goTrain','primary')}</div><div class="heroart">${illustration('chest',1)}<div class="eyebrow" style="text-align:center;margin-bottom:20px">FUERZA ÚTIL. PROGRESO REAL.</div></div></section><div class="stats">${stat('Próxima sesión',`0${n==='A'?1:2} <span class="lime">/ ${n}</span>`,n==='A'?'Chest & Shoulders':'Back & Arms')}${stat('Tiempo estimado','45–60 <small>MIN</small>','Express disponible: 25–35 min')}${stat('Esta semana',`${done} <small>/ ${state.profile.days||2}</small>`,'sesiones · últimos 7 días')}${stat('Tu programa',`${Math.min(100,Math.round(state.sessions.filter(s=>s.complete&&s.type!=='C').length/24*100))}<small>%</small>`,'24 sesiones base · A + B')}</div><div class="grid"><div class="stack"><section class="card"><div class="cardhead"><h3>Tu plan de entrenamiento</h3><span class="eyebrow">FULL BODY</span></div><div class="sessionlist">${sessionTile('A','Chest & Shoulders','Pecho · espalda · piernas · hombros',n)}${sessionTile('B','Back & Arms','Espalda · pecho · piernas · brazos',n)}${sessionTile('C','Executive Upper Body','Torso + piernas · sesión opcional',n)}</div><p class="fine" style="margin-top:15px">Deja al menos un día entre sesiones. La tercera suma; las dos primeras sostienen el plan.</p></section><section class="card"><div class="cardhead"><h3>¿Cómo llegas hoy?</h3><span class="eyebrow">CHECK-IN</span></div>${energyControls()}<p class="fine" style="margin-top:14px">Ajusta el esfuerzo a tu día. Entrenar agotado no exige terminar exhausto.</p></section></div><div class="stack"><section class="card"><div class="cardhead"><h3>Disciplina semanal</h3><span class="badge">${done} COMPLETADAS</span></div><div class="weekdays">${Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);let ok=state.sessions.some(s=>s.complete&&new Date(s.ended).toDateString()===d.toDateString());return `<div class="weekday ${ok?'done':''}">${['D','L','M','X','J','V','S'][d.getDay()]}<b>${ok?'✓':d.getDate()}</b></div>`}).join('')}</div><div class="bar"><i style="width:${Math.min(100,done/(state.profile.days||2)*100)}%"></i></div><p class="fine">${done>=2?'Base semanal cumplida. Recupera y sigue así.':'Tu objetivo: dos buenas sesiones. Una a una.'}</p></section><section class="card"><div class="cardhead"><h3>Executive Nutrition</h3>${btn('Ver plan ↗','nav','small ghost','data-page="nutrition"')}</div><p class="fine">${t?`${fmt(t.kcal)} kcal estimadas · ${fmt(t.protein)} g de proteína`:'Tu menú semanal, sin pescado ni marisco.'}</p>${m.slice(1,3).map((x,i)=>`<div class="mealmini"><time>${esc(state.schedule[i+1])}</time><div><h4>${mealSlots[i+1]}</h4><p>${esc(x.name)}</p></div></div>`).join('')}</section></div></div>${!state.profile.age?`<div class="notice row"><span>Personaliza tu perfil para ajustar el programa y las raciones. Puedes comenzar a entrenar sin rellenarlo todo.</span>${btn('Configurar','nav','small','data-page="settings"')}</div>`:''}`}
function sessionTile(id,name,desc,n){return `<div class="sessiontile ${id===n?'current':''}"><span class="letter">${id}</span><div><h3>${name}</h3><p>${desc}</p></div>${btn(id==='C'?'Opcional ↗':'Ver →','choose','small ghost',`data-id="${id}"`)}</div>`}
function energyControls(){return `<div class="pills energy">${[['high','↗ Alta','Listo para todo'],['normal','◉ Normal','Ritmo sostenible'],['low','↘ Agotado','Executive Express']].map(([id,label,desc])=>btn(`<strong>${label}</strong><span>${desc}</span>`,'energy',energy===id?'selected':'',`data-id="${id}" aria-pressed="${energy===id}"`)).join('')}</div>`}
function train(){if(state.active)return activeWorkout();let s=makeSession(state,plans,selected,energy,deload);return `${title('ENTRENAMIENTO / PREPARACIÓN','Una sesión. Un paso a la vez.')}<div class="grid"><section class="card"><div class="cardhead"><h3>Elige tu sesión</h3><span class="badge">SEMANA ${weekNumber(state)}</span></div><div class="pills">${['A','B','C'].map(x=>btn(`SESIÓN ${x}${x==='C'?' · OPCIONAL':''}`,'choose',selected===x?'selected':'',`data-id="${x}"`)).join('')}</div><div class="divider"></div><h3>¿Cómo llegas hoy?</h3><div style="margin-top:16px">${energyControls()}</div><div class="notice">${s.express?'EXECUTIVE EXPRESS · 25–35 min. Menos volumen, mismo compromiso.':s.adapt?'ADAPTACIÓN · 35–50 min. Aprende los movimientos durante las primeras dos semanas.':'PROGRAMA ESTÁNDAR · 45–60 min. Descansos completos y técnica estable.'}<br>RIR objetivo: ${s.rir}. RIR = repeticiones que aún podrías hacer.</div><label class="check"><input type="checkbox" id="deload" ${deload?'checked':''}> Reducir volumen esta sesión (descarga / mala recuperación)</label>${state.profile.limitations?`<div class="notice warn">Limitaciones indicadas: ${esc(state.profile.limitations)}. La aplicación no diagnostica lesiones. Excluye los ejercicios contraindicados en Ajustes y confirma alternativas con un profesional.</div>`:''}<p class="fine" style="margin:18px 0">Si notas dolor inusual, mareo, dolor torácico o síntomas preocupantes, detente y busca valoración. No entrenes con dolor.</p>${btn('INICIAR SESIÓN '+selected+' →','start','primary','style="width:100%"')}<p class="fine" style="margin-top:12px">5 min de calentamiento + series ligeras de aproximación antes de las cargas de trabajo.</p></section><section class="card"><div class="cardhead"><h3>Tu hoja de ruta</h3><span class="eyebrow">${s.plan.reduce((a,e)=>a+e.sets,0)} SERIES</span></div><div class="stack">${s.plan.map((x,i)=>`<div class="row"><div><h3 style="font-size:13px">${String(i+1).padStart(2,'0')} / ${E[x.id].name}</h3><p class="fine">${x.sets} × ${x.min}–${x.max} ${E[x.id].timed?'s':'reps'} · ${x.rest}s descanso</p></div>${btn('↗','exercise','small ghost',`data-id="${x.id}" aria-label="Ver ${E[x.id].name}"`)}</div>`).join('')}</div></section></div>`}
function activeWorkout(){let s=state.active;if(!s.warmup)return `${title('SESIÓN '+s.type,'Primero, prepara el cuerpo.')}<section class="card"><h3>5 minutos · bicicleta o cinta</h3><p style="margin:14px 0">Ritmo cómodo, movilidad suave y respiración tranquila. Después, realiza 1–2 series ligeras del primer ejercicio.</p>${s.timer?timerUI(s.timer):btn('INICIAR 5 MINUTOS','warmtimer','primary')}<div style="margin-top:18px">${btn('CALENTAMIENTO COMPLETADO →','warmdone','ghost')}</div><p class="fine" style="margin-top:14px">Puedes marcarlo si ya calentaste antes de abrir la app.</p></section>`;let x=s.plan[s.index],e=E[x.id],rec=recommendation(state,x.id,x.min,x.max);let total=s.plan.reduce((a,e)=>a+e.sets,0),done=s.plan.reduce((a,e)=>a+e.done,0);return `${title(`SESIÓN ${s.type} / ${s.express?'EXECUTIVE EXPRESS':'EXECUTIVE TRAINING'}`,e.name,`<span class="badge">${s.index+1} / ${s.plan.length}</span>`)}<div class="bar"><i style="width:${done/total*100}%"></i></div><div class="grid"><div class="stack"><div class="exerciseart">${illustration(e,phase)}</div><div class="row"><span class="eyebrow">${phase?'02 / MOVIMIENTO':'01 / POSICIÓN INICIAL'}</span>${btn('Cambiar vista ⇄','phase','small')}</div><section class="card"><ol class="technique">${e.tips.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p class="fine">${esc(e.breath)}</p><details><summary>Errores que debes evitar</summary><p class="fine">${esc(e.errors)}</p></details>${btn('MÁQUINA OCUPADA — CAMBIAR','swap','ghost','style="width:100%"')}${x.id!==x.original?btn('Volver al ejercicio original','original','small ghost','style="margin-top:8px;width:100%"'):''}</section></div><section class="card">${s.timer?timerUI(s.timer):''}<div class="row"><div><div class="eyebrow">${x.done>=x.sets?'EJERCICIO COMPLETADO':'SERIE ACTUAL'}</div><div class="trainingnumber">${Math.min(x.done+1,x.sets)} <small class="muted">/ ${x.sets}</small></div></div><div style="text-align:right"><div class="eyebrow">OBJETIVO</div><h2>${x.min}–${x.max} <small>${e.timed?'s':'reps'}</small></h2></div></div><div class="notice">${esc(rec.text)}${rec.weight!==''?`<br>Referencia orientativa: ${rec.weight} kg`:''}<br>RIR objetivo ${s.rir}. ${e.equipment==='Mancuernas'?'Registra kg por mancuerna.':e.equipment==='Peso corporal'?'Registra 0 kg si no usas carga externa.':'Las cargas de máquinas distintas no son equivalentes.'}</div>${e.timed&&!s.timer&&x.done<x.sets?btn('CRONOMETRAR '+x.min+' SEGUNDOS','effort','ghost','style="width:100%;margin-bottom:12px"'):''}${x.done<x.sets?`<form id="setform"><div class="fieldgrid"><label>Peso utilizado (kg)<input name="weight" type="number" min="0" max="1000" step="0.5" required value="${rec.weight}" inputmode="decimal" placeholder="0"></label><label>${e.timed?'Segundos realizados':'Repeticiones reales'}<input name="reps" type="number" min="1" max="600" required value="${x.min}" inputmode="numeric"></label><label>RIR (opcional)<select name="rir"><option value="">No registrado</option>${[0,1,2,3,4,5].map(n=>`<option value="${n}">${n}${n===5?' o más':''}</option>`).join('')}</select></label><label class="check"><input name="technique" type="checkbox"> Técnica estable</label></div>${btn('✓ COMPLETAR SERIE','submitSet','primary',`type="submit" style="width:100%" ${s.timer?'disabled':''}`)}</form>`:btn(s.index===s.plan.length-1?'TERMINAR ENTRENAMIENTO ✓':'SIGUIENTE EJERCICIO →','advance','primary','style="width:100%;margin-top:20px"')}<div class="divider"></div><p class="fine">Guardado automático tras cada serie. Puedes cerrar y continuar después.</p><div class="pills" style="margin-top:15px">${btn('Guardar y salir','nav','small ghost','data-page="dashboard"')}${btn('Terminar antes','early','small danger')}</div></section></div>`}
function timerUI(t){return `<div class="timerbox"><div class="eyebrow">${t.kind==='effort'?'EJERCICIO':state.active?.warmup?'RECUPERACIÓN':'CALENTAMIENTO'} · ${t.paused?'EN PAUSA':'EN CURSO'}</div><div class="timerdigits" id="timer" role="timer">${clock(remaining(t))}</div><div class="pills" style="justify-content:center">${btn(t.paused?'Continuar':'Pausar','pause','small')}${btn('+30 s','add30','small')}${btn('Saltar','skip','small ghost')}</div></div>`}
function library(){let filtered=Object.values(E).filter(e=>(filter==='Todos'||e.group===filter)&&e.name.toLowerCase().includes(query.toLowerCase()));return `${title('BIBLIOTECA / MOVIMIENTO','Domina lo esencial.',`<span class="badge">${Object.keys(E).length} EJERCICIOS</span>`)}<div class="fieldgrid" style="margin-bottom:20px"><label>Buscar ejercicio<input id="search" value="${esc(query)}" placeholder="Press, remo, bíceps…" type="search"></label><label>Grupo muscular<select id="filter">${['Todos',...new Set(Object.values(E).map(e=>e.group))].map(g=>`<option ${filter===g?'selected':''}>${g}</option>`).join('')}</select></label></div><div class="exercises">${filtered.map(e=>`<article class="card exerciseCard"><div class="exerciseart">${illustration(e,0)}</div><div class="details"><span class="eyebrow">${e.group}</span><h3>${e.name}</h3><p class="fine">${e.equipment}</p>${btn('Ver técnica →','exercise','small',`data-id="${e.id}"`)}</div></article>`).join('')}</div>`}
function exerciseModal(id){const e=E[id];modal(e.name,`<span class="badge">${e.group} · ${e.equipment}</span><div class="artphases" style="margin:16px 0"><div class="exerciseart">${illustration(e,0)}</div><div class="exerciseart">${illustration(e,1)}</div></div><ol class="technique">${e.tips.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p class="fine">${e.breath}</p><div class="notice warn">Evita: ${e.errors}</div><h3>Alternativas</h3><div class="pills" style="margin-top:12px">${e.alternatives.map(a=>btn(E[a].name,'exercise','small',`data-id="${a}"`)).join('')}</div>`)}
function nutrition(){let t=targets(state.profile),m=meals(),tot=m.reduce((a,x)=>{for(let k in a)a[k]+=x.macros[k];return a},{kcal:0,p:0,c:0,f:0,fiber:0});return `${title('COMBUSTIBLE / RECUPERACIÓN','Executive Nutrition',btn('Horarios y avisos','schedule','small'))}<div class="notice ${state.profile.tolerance?'':'warn'}">${state.profile.tolerance?'Preferencias confirmadas. Sin pescado, marisco ni verduras rechazadas.':'Menú propuesto pendiente de confirmar tolerancias: lácteos, huevo, trigo, avena, frutos secos, pollo, pavo y ternera. Revisa antes de seguirlo. '+btn('Revisar tolerancias','tolerance','small')}</div><div class="stats">${stat('Menú del día',fmt(tot.kcal)+' <small>kcal</small>',t?'Objetivo estimado: '+fmt(t.kcal):'Raciones de ejemplo · configura tu perfil')}${stat('Proteína',fmt(tot.p)+' <small>g</small>',t?'Referencia: '+fmt(t.protein)+' g/día':'Referencia: 1,4–2,0 g/kg/día')}${stat('Carbohidratos',fmt(tot.c)+' <small>g</small>','Energía para rendir')}${stat('Fibra',fmt(tot.fiber)+' <small>g</small>','Fruta · integrales · alimentos tolerados')}</div><div class="row" style="margin-bottom:22px;flex-wrap:wrap"><div class="pills">${week.map((d,i)=>btn(d.day.slice(0,3),'day',day===i?'selected':'',`data-id="${i}"`)).join('')}</div>${btn('Lista de compra ↗','shopping','small')}</div><div class="meals">${m.map((x,i)=>`<article class="card mealcard"><div class="row"><span class="eyebrow">0${i+1} / ${mealSlots[i]}</span><span class="badge">${esc(state.schedule[i])}</span></div><h3>${esc(x.name)}</h3><div class="mealitems">${x.items.map(([id,g])=>`${fmt(g)} g · ${foods[id].name} <span class="muted">(${foods[id].state})</span>`).join('<br>')}</div><div class="macro">${fmt(x.macros.kcal)} kcal &nbsp; P ${fmt(x.macros.p)} · C ${fmt(x.macros.c)} · G ${fmt(x.macros.f)} g</div><div class="pills" style="margin-top:16px">${btn('⇄ Cambiar','swapmeal','small',`data-id="${i}"`)}${btn('Raciones','portions','small ghost',`data-id="${i}"`)}${btn('☆','favorite','small ghost',`data-id="${i}" aria-label="Guardar comida favorita"`)}</div></article>`).join('')}</div><div class="grid equal" style="margin-top:20px"><section class="card"><h3>Tu entrenamiento de tarde</h3><div class="mealmini"><time>${esc(state.schedule[4])}</time><div><h4>Snack previo · si lo necesitas</h4><p>Un plátano (120 g) si han pasado varias horas desde la comida. Puedes mover aquí la fruta de la merienda; no hace falta duplicarla.</p></div></div><p class="fine">Agua antes y durante, según sed y sudoración. Después, tu cena con proteína. Evita cenas incómodamente grandes y estimulantes tardíos si afectan al sueño.</p></section><section class="card"><h3>Preparación anticipada</h3><p class="fine" style="margin-top:15px">Cocina 2–3 raciones de pollo o pavo, arroz y patata. Refrigera pronto en recipientes individuales y congela lo que no vayas a consumir pronto. El arroz exige especial cuidado de enfriado y conservación.</p><details><summary>Opciones rápidas de supermercado</summary><p class="fine">Yogur natural alto en proteína + fruta; arroz cocido + pollo cocinado sin salsas; pan integral + queso fresco + tomate. Comprueba ingredientes y ajusta según la etiqueta.</p></details><details><summary>Fibra, calcio y variedad</summary><p class="fine">Prioriza fruta variada, avena, integrales y aguacate. Lácteos tolerados aportan calcio; patata y fruta aportan potasio. Este menú no verifica todos los micronutrientes. Las restricciones amplias o condiciones médicas requieren revisión profesional. No existe pérdida de grasa localizada.</p></details>${btn('Ver favoritos ('+state.favorites.length+')','favorites','small ghost')}</section></div>`}
function chart(values,label){if(values.length<2)return `<div class="empty">Registra al menos dos puntos para ver la tendencia de ${label}.</div>`;let min=Math.min(...values),max=Math.max(...values),span=max-min||1;let pts=values.map((v,i)=>`${15+i/(values.length-1)*310},${115-(v-min)/span*85}`).join(' ');return `<svg class="chart" viewBox="0 0 340 140" role="img" aria-label="${esc(label)}: ${values.map(v=>Math.round(v*10)/10).join(', ')}"><path d="M15 115H325 M15 30H325" stroke="#343e2e" stroke-dasharray="3 5"/><polyline points="${pts}" fill="none" stroke="#c2f66c" stroke-width="2.5"/>${pts.split(' ').map(p=>`<circle cx="${p.split(',')[0]}" cy="${p.split(',')[1]}" r="3" fill="#c2f66c"/>`).join('')}<text x="15" y="135" fill="#a3aa9b" font-size="10">${min.toFixed(1)}–${max.toFixed(1)} · orden cronológico</text></svg>`}
function progress(){let history=state.sessions.filter(s=>s.complete),logs=recent().flatMap(s=>s.logs),groups={};logs.forEach(l=>{let g=E[l.id]?.group||'Otro';groups[g]=(groups[g]||0)+1});let chosen=state.chartExercise||'chest',eh=history.map(s=>s.logs.filter(l=>l.id===chosen)).filter(l=>l.length);return `${title('DATOS / SIN ATAJOS','Tu trabajo deja huella.',btn('+ Registrar medidas','measure','primary'))}<div class="stats">${stat('Sesiones',history.length,'completadas')}${stat('Últimos 7 días',recent().length,'sesiones registradas')}${stat('Series',logs.length,'últimos 7 días')}${stat('Adherencia',Math.min(100,Math.round(recent().length/(state.profile.days||2)*100))+'%','sobre objetivo semanal')}</div><div class="grid equal"><section class="card"><h3>Peso corporal · kg</h3>${chart(state.measurements.filter(x=>x.weight).map(x=>x.weight),'peso')}</section><section class="card"><h3>Perímetro de cintura · cm</h3>${chart(state.measurements.filter(x=>x.waist).map(x=>x.waist),'cintura')}</section><section class="card"><label>Historial de cargas<select id="chartExercise">${Object.values(E).map(e=>`<option value="${e.id}" ${e.id===chosen?'selected':''}>${e.name}</option>`).join('')}</select></label>${chart(eh.map(l=>Math.max(...l.map(x=>x.weight))),'carga kg')}<h3>Repeticiones medias</h3>${chart(eh.map(l=>l.reduce((a,x)=>a+x.reps,0)/l.length),'repeticiones')}</section><section class="card"><h3>Series por grupo muscular</h3><p class="fine">Últimos 7 días · grupo principal; el trabajo indirecto no se suma.</p>${Object.entries(groups).length?Object.entries(groups).map(([g,n])=>`<div class="row" style="margin-top:18px"><span>${g}</span><span class="lime">${n}</span></div><div class="bar"><i style="width:${n/Math.max(...Object.values(groups))*100}%"></i></div>`).join(''):'<div class="empty">Completa tu primera sesión para empezar.</div>'}<p class="fine">Las cargas y medidas muestran tendencias, no una medición directa de músculo o grasa.</p></section></div><section class="card" style="margin-top:20px"><div class="cardhead"><h3>Registro de sesiones</h3><span class="badge">${state.sessions.length}</span></div><div class="tablewrap"><table><thead><tr><th>Fecha</th><th>Sesión</th><th>Series</th><th>Estado</th><th>Detalle</th></tr></thead><tbody>${state.sessions.slice().reverse().map((s,i)=>`<tr><td>${new Date(s.ended||s.started).toLocaleDateString('es-ES')}</td><td>${s.type}${s.express?' · Express':''}</td><td>${s.logs.length}</td><td>${s.complete?'Completa':'Parcial'}</td><td>${btn('Ver','history','small',`data-id="${state.sessions.length-1-i}"`)}</td></tr>`).join('')}</tbody></table></div></section><section class="card" style="margin-top:20px"><div class="cardhead"><h3>Fotos privadas de seguimiento</h3><label>+ Añadir foto<input id="photo" type="file" accept="image/*" style="max-width:190px"></label></div><p class="fine">Solo en este navegador. Sin envíos a terceros. Las copias JSON incluyen tus fotos; guárdalas con cuidado.</p><div class="photoGrid" style="margin-top:16px">${state.photos.map((p,i)=>`<div><img src="${/^data:image\/(jpeg|png|webp);base64,/.test(p.data)?p.data:''}" alt="Foto personal del ${esc(p.date)}"><p class="fine">${esc(p.date)}</p>${btn('Eliminar','deletephoto','small danger',`data-id="${i}"`)}</div>`).join('')}</div></section>`}
function field(name,label,type='number',min='',max='',placeholder=''){return `<label>${label}<input name="${name}" type="${type}" ${min?`min="${min}"`:''} ${max?`max="${max}"`:''} ${type==='number'?'step="any"':''} value="${esc(state.profile[name]||'')}" placeholder="${placeholder}"></label>`}
function select(name,label,opts){return `<label>${label}<select name="${name}">${opts.map(([v,t])=>`<option value="${v}" ${state.profile[name]===v?'selected':''}>${t}</option>`).join('')}</select></label>`}
function settings(){return `${title('CONFIGURACIÓN / PERFIL','El plan se adapta a ti.')}<div class="grid"><section class="card"><h3>Tu punto de partida</h3><p class="fine" style="margin:10px 0 20px">Todos los datos permanecen en tu dispositivo. Para calcular raciones necesitamos edad, altura y peso.</p><form id="profile"><div class="fieldgrid">${field('age','Edad','number',18,85)}${field('height','Altura (cm)','number',130,220)}${field('weight','Peso (kg)','number',40,220)}${field('waist','Cintura (cm) · opcional','number',40,200)}${select('level','Nivel',[['beginner','Principiante'],['intermediate','Intermedio'],['advanced','Experimentado']])}${select('experience','Experiencia con máquinas',[['yes','Sé ajustarlas'],['no','Necesito aprender']])}${select('time','Minutos disponibles',[[30,'30 min · Express'],[45,'45 min'],[55,'55 min'],[60,'60 min']])}${select('days','Sesiones semanales',[[2,'2 + tercera opcional'],[3,'3 sesiones']])}${select('goal','Prioridad',[['recomp','Recomposición'],['muscle','Ganar músculo'],['fat','Reducir grasa gradualmente'],['maintenance','Mantener']])}${select('activity','Actividad cotidiana',[['low','Trabajo sedentario'],['moderate','Camino bastante'],['high','Trabajo físicamente activo']])}<label class="full">Lesiones o limitaciones físicas<textarea name="limitations" placeholder="Opcional. No se interpretan como un diagnóstico.">${esc(state.profile.limitations||'')}</textarea></label><label class="full">Preferencias / intolerancias adicionales<textarea name="foodNotes" placeholder="El menú excluye pescado, marisco y verduras no aceptadas.">${esc(state.profile.foodNotes||'')}</textarea></label><label class="check full"><input type="checkbox" name="medical" ${state.profile.medical?'checked':''}> Enfermedad o medicación que afecta a la dieta: desactivar estimación automática.</label><label class="check full"><input type="checkbox" name="tolerance" ${state.profile.tolerance?'checked':''}> Confirmo que tolero los ingredientes del menú y he revisado mis restricciones adicionales.</label></div>${btn('GUARDAR PERFIL','saveprofile','primary','type="submit"')}</form><details><summary>Material disponible</summary><div class="stack">${['Máquina','Polea','Mancuernas','Peso corporal'].map(x=>`<label class="check"><input class="equipment" type="checkbox" value="${x}" ${(!state.profile.material||state.profile.material.includes(x))?'checked':''}>${x}</label>`).join('')}</div></details><details><summary>Excluir movimientos contraindicados</summary><p class="fine">Selecciona solo según tus limitaciones conocidas o indicación profesional. Los ejercicios excluidos no se ofrecen como alternativas.</p><div class="stack">${Object.values(E).map(e=>`<label class="check"><input class="excluded" type="checkbox" value="${e.id}" ${(state.profile.excluded||[]).includes(e.id)?'checked':''}>${e.name}</label>`).join('')}</div></details></section><div class="stack"><section class="card"><h3>Datos y copias de seguridad</h3><p class="fine" style="margin:14px 0">El almacenamiento del navegador puede borrarse. Exporta una copia periódica. No hay cuenta ni sincronización entre dispositivos.</p><div class="stack">${btn('Exportar datos JSON','export') }<label>Importar copia JSON<input id="import" type="file" accept="application/json,.json"></label>${btn('Solicitar almacenamiento persistente','persistent','small ghost')}${btn('Borrar todos mis datos','reset','small danger')}</div></section><section class="card"><h3>Instala SealGym</h3><p class="fine" style="margin-top:14px">En Safari de iPhone: Compartir → Añadir a pantalla de inicio. Abre la app una vez con conexión para preparar el modo offline. El alojamiento privado puede pedir acceso al abrir el enlace por primera vez.</p><p class="fine" id="offlineState" style="margin-top:10px">${navigator.serviceWorker?.controller?'Recursos offline preparados.':'Preparando recursos offline…'}</p>${btn('Horarios y alarmas','schedule','small','style="margin-top:16px"')}</section><section class="card"><h3>Programa de 12 semanas</h3><p class="fine" style="margin-top:14px">Semanas 1–2: adaptación si eres principiante. Semanas 3–6: consolidación. Semanas 7–10: doble progresión. Semanas 11–12: consolidar y evaluar. Avanza según sesiones A/B completadas, sin subir peso por calendario.</p><p class="fine" style="margin-top:12px">El sistema propone cargas solo con historial del mismo ejercicio. Si cae el rendimiento o cuesta recuperarte, activa descarga. No garantiza resultados ni reemplaza supervisión.</p><div class="pills" style="margin-top:16px"><a href="docs/EVIDENCE.md" target="_blank" rel="noopener">Fuentes científicas ↗</a></div></section></div></div>`}
function notify(text){toast(text);try{navigator.vibrate?.([180,80,180]);if(audioCtx){let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.connect(g);g.connect(audioCtx.destination);g.gain.value=.12;o.frequency.value=660;o.start();o.stop(audioCtx.currentTime+.25)}if('Notification'in window&&Notification.permission==='granted')navigator.serviceWorker?.ready.then(r=>r.showNotification('SealGym',{body:text,icon:'icon-192.png',tag:'sealgym'})).catch(()=>{})}catch{}}
function tick(){let t=state.active?.timer;if(t){const n=remaining(t);if($('#timer'))$('#timer').textContent=clock(n);if(n===0&&!t.paused){state.active.timer=null;persist();notify(t.kind==='effort'?'Tiempo cumplido. Registra tus segundos reales.':state.active.warmup?'Descanso completado. Siguiente serie.':'Calentamiento terminado.');if(page==='train')render()}}if(state.reminders){let d=new Date(),key=d.toDateString()+' '+d.getHours()+':'+d.getMinutes();if(notifyMinute!==key){notifyMinute=key;let hh=String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0'),i=state.schedule.indexOf(hh);if(i>=0)notify((mealSlots[i]||'Snack previo opcional')+': revisa tu plan de alimentación.')}}}
function finish(partial=false){let s=state.active;s.ended=Date.now();s.complete=!partial;s.timer=null;state.sessions.push(s);state.active=null;persist();page='progress';render();toast(partial?'Sesión parcial guardada. Recuperarte también cuenta.':'Sesión completada. Buen trabajo. Ahora, recupera.');}
function swapModal(){let x=state.active.plan[state.active.index],e=E[x.original];let available=e.alternatives.filter(id=>!state.profile.excluded.includes(id)&&(!state.profile.material||state.profile.material.includes(E[id].equipment)));available.sort((a,b)=>E[a].difficulty-E[b].difficulty);modal('Máquina ocupada',`<p class="fine" style="margin-bottom:15px">Tú indicas la ocupación. Elige una alternativa sin dolor. Conservaremos las series pendientes; las cargas no se trasladan entre máquinas.</p><div class="stack">${available.map(id=>btn(`<strong>${E[id].name}</strong><br><span class="fine">${E[id].equipment} · ${E[id].group}</span>`,'replace','ghost',`data-id="${id}"`)).join('')||'<p>No hay alternativas compatibles con el material y las exclusiones configuradas.</p>'}</div>`)}
function scheduleModal(){modal('Horarios y avisos',`<p class="fine" style="margin-bottom:18px">Horarios locales de tu dispositivo. Los avisos de esta web funcionan mientras está activa. Con la app cerrada o el iPhone bloqueado no se garantizan; importa el calendario para usar sus alertas.</p><form id="scheduleform"><div class="fieldgrid">${[...mealSlots,'Snack opcional'].map((n,i)=>`<label>${n}<input type="time" name="t${i}" value="${esc(state.schedule[i])}" required></label>`).join('')}</div><label class="check" style="margin-top:15px"><input name="enabled" type="checkbox" ${state.reminders?'checked':''}> Avisos mientras la app está abierta</label>${btn('Guardar horarios','saveSchedule','primary','type="submit"')}</form><div class="pills" style="margin-top:16px">${btn('Permitir notificaciones','permission','small')}${btn('Exportar calendario .ics','calendar','small')}</div><p class="fine" style="margin-top:14px">El archivo crea recordatorios diarios durante 12 semanas. Revísalos antes de importarlos. Cada importación adicional puede duplicarlos.</p>`)}
function download(name,content,type){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function exportCalendar(){let d=new Date(),date=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('');let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//SEALGYM//Executive Nutrition//ES','CALSCALE:GREGORIAN'];state.schedule.forEach((t,i)=>lines.push('BEGIN:VEVENT',`UID:sealgym-${date}-${i}@local`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+/,'')}`,`DTSTART:${date}T${t.replace(':','')}00`,'DURATION:PT15M','RRULE:FREQ=DAILY;COUNT=84',`SUMMARY:SealGym - ${[...mealSlots,'Snack opcional'][i]}`,'DESCRIPTION:Consulta el menu de SealGym. Horario editable.','BEGIN:VALARM','TRIGGER:PT0M','ACTION:DISPLAY','DESCRIPTION:Hora de tu comida SealGym','END:VALARM','END:VEVENT'));lines.push('END:VCALENDAR');download('sealgym-horarios.ics',lines.join('\r\n')+'\r\n','text/calendar;charset=utf-8');toast('Calendario descargado. Impórtalo y revisa sus alertas.');}
function validState(value){let x=validateImport(value);for(let s of [...x.sessions,...(x.active?[x.active]:[])]){if(s.logs.some(l=>!E[l.id]))throw Error('Ejercicio desconocido');if(s.plan?.some(e=>!E[e.id]||!E[e.original]||!Number.isInteger(e.sets)||e.sets<1||e.sets>10||!Number.isInteger(e.done)||e.done<0||e.done>e.sets))throw Error('Plan inválido')}if(!Array.isArray(x.schedule)||x.schedule.length!==5||x.schedule.some(t=>!/^([01]\d|2[0-3]):[0-5]\d$/.test(t)))throw Error('Horarios inválidos');if(!Array.isArray(x.photos)||x.photos.some(p=>!/^data:image\/(jpeg|png|webp);base64,/.test(p.data)))throw Error('Fotos inválidas');if(!Array.isArray(x.favorites)||!x.overrides||typeof x.overrides!=='object')throw Error('Menú inválido');for(let m of [...x.favorites,...Object.values(x.overrides)]){if(typeof m.name!=='string'||!Array.isArray(m.items)||m.items.some(([id,g])=>!foods[id]||!Number.isFinite(g)||g<=0||g>2000))throw Error('Comida inválida')}return x}
document.addEventListener('click',async ev=>{let b=ev.target.closest('[data-act]');if(!b)return;let a=b.dataset.act,id=b.dataset.id;if(['submitSet','saveprofile','saveSchedule','savePortions','saveMeasure'].includes(a))return;try{if(a==='close'){$('#dialog').close();return}if(a==='nav'){page=b.dataset.page;render();window.scrollTo(0,0)}else if(a==='goTrain'){selected=nextSession(state);page='train';render();window.scrollTo(0,0)}else if(a==='choose'){selected=id;page='train';render()}else if(a==='energy'){energy=id;render()}else if(a==='start'){let h=state.sessions.filter(s=>s.complete).at(-1);if(h&&Date.now()-h.ended<36*3600000&&!confirm('Tu última sesión fue hace menos de 36 horas. Considera recuperar otro día. ¿Continuar de todos modos?'))return;let s=makeSession(state,plans,selected,energy,deload);s.plan.forEach(x=>x.group=E[x.id].group);if(!s.plan.length){toast('No hay ejercicios disponibles. Revisa tus exclusiones.');return}state.active=s;try{audioCtx=new(window.AudioContext||window.webkitAudioContext)();await audioCtx.resume()}catch{}await persist();render()}else if(a==='effort'){let x=state.active.plan[state.active.index];state.active.timer={end:Date.now()+x.min*1000,left:x.min,paused:false,kind:'effort'};await persist();render()}else if(a==='warmtimer'){state.active.timer={end:Date.now()+300000,left:300,paused:false};await persist();render()}else if(a==='warmdone'){state.active.warmup=true;state.active.timer=null;await persist();render()}else if(a==='pause'){let s=state.active;s.timer=s.timer.paused?resumeTimer(s.timer):pauseTimer(s.timer);await persist();render()}else if(a==='add30'){let t=state.active.timer;if(t.paused)t.left+=30;else t.end+=30000;await persist();tick()}else if(a==='skip'){state.active.timer=null;await persist();render()}else if(a==='phase'){phase=phase?0:1;render()}else if(a==='advance'){state.active=advance(state.active);if(state.active.complete)finish();else{await persist();render();window.scrollTo(0,0)}}else if(a==='early'){if(confirm('¿Guardar lo realizado como sesión parcial y finalizar?'))finish(true)}else if(a==='exercise')exerciseModal(id);else if(a==='swap')swapModal();else if(a==='replace'||a==='original'){let x=state.active.plan[state.active.index],to=a==='original'?x.original:id;state.active.swaps.push({from:x.id,to,at:Date.now(),pending:x.sets-x.done});if(Boolean(E[x.id].timed)!==Boolean(E[to].timed)){x.min=E[to].timed?30:10;x.max=E[to].timed?45:15;}x.id=to;x.group=E[to].group;await persist();$('#dialog').close();render();toast('Ejercicio actualizado. Usa una carga de prueba prudente.')}else if(a==='day'){day=+id;render()}else if(a==='swapmeal'){let original=meals()[+id],key=day+':'+id;state.overrides[key]=replaceMeal(day,+id,state.profile,1+((state.swapCounts||{})[key]||0));state.swapCounts={...state.swapCounts,[key]:1+((state.swapCounts||{})[key]||0)};await persist();render();toast('Comida cambiada. Revisa los totales del día.')}else if(a==='portions'){let m=meals()[+id];modal('Ajustar cantidades',`<form id="portionsform" data-id="${id}"><p class="fine">${esc(m.name)}. Al guardar se recalculan macros y compra.</p><div class="stack" style="margin-top:16px">${m.items.map(([f,g])=>`<label>${foods[f].name} · ${foods[f].state}<input name="${f}" type="number" min="1" max="2000" step="1" value="${Math.round(g)}" required></label>`).join('')}</div>${btn('Guardar raciones','savePortions','primary','type="submit"')}</form>`)}else if(a==='favorite'){let m=meals()[+id];state.favorites.push(m);await persist();toast('Comida guardada en favoritos.')}else if(a==='favorites'){modal('Tus comidas favoritas',`<div class="stack">${state.favorites.map((m,i)=>`<div><h3>${esc(m.name)}</h3><p class="fine">${m.items.map(([f,g])=>fmt(g)+' g '+foods[f].name).join(' · ')}</p>${btn('Usar como comida de hoy','usefavorite','small',`data-id="${i}"`)}</div>`).join('')||'<p>Aún no tienes favoritos. Pulsa ☆ en una comida.</p>'}</div>`)}else if(a==='usefavorite'){state.overrides[day+':1']=structuredClone(state.favorites[+id]);await persist();$('#dialog').close();render()}else if(a==='shopping'){let list=shoppingList(state.profile,state.overrides);modal('Lista de compra · 7 días',`<p class="fine">Cantidades comestibles; ajusta envases, merma y alimentos que ya tienes. Snack opcional no incluido.</p><div class="stack" style="margin-top:20px">${list.map(x=>`<label class="check"><input type="checkbox"><span>${x.name} · <b>${fmt(x.grams)} g</b><br><small>${x.state}</small></span></label>`).join('')}</div>${btn('Descargar lista','downloadShopping','primary','style="margin-top:20px"')}`)}else if(a==='downloadShopping'){download('sealgym-compra.txt',shoppingList(state.profile,state.overrides).map(x=>`${x.name}: ${Math.round(x.grams)} g (${x.state})`).join('\n'),'text/plain')}else if(a==='tolerance'){page='settings';render();window.scrollTo(0,0)}else if(a==='schedule')scheduleModal();else if(a==='calendar')exportCalendar();else if(a==='permission'){if(!('Notification'in window)){toast('Notificaciones no disponibles. Usa el calendario.');return}let p=await Notification.requestPermission();toast(p==='granted'?'Permiso concedido. Avisos mientras la app está activa.':'Sin permiso. Puedes usar los avisos del calendario.')}else if(a==='measure'){modal('Registrar medidas',`<form id="measureform"><div class="fieldgrid"><label>Fecha<input type="date" name="date" required value="${new Date().toLocaleDateString('sv-SE')}"></label><label>Peso (kg)<input name="weight" type="number" min="30" max="250" step="0.1"></label><label>Cintura (cm) · opcional<input name="waist" type="number" min="40" max="200" step="0.1"></label></div>${btn('Guardar medidas','saveMeasure','primary','type="submit"')}</form>`)}else if(a==='history'){let s=state.sessions[+id];modal('Sesión '+s.type,`<div class="tablewrap"><table><tr><th>Ejercicio</th><th>Kg</th><th>Reps / s</th><th>RIR</th></tr>${s.logs.map(l=>`<tr><td>${esc(E[l.id].name)}</td><td>${l.weight}</td><td>${l.reps}</td><td>${l.rir??'—'}</td></tr>`).join('')}</table></div><p class="fine">${(s.swaps||[]).length} sustituciones registradas.</p>`)}else if(a==='deletephoto'){if(confirm('¿Eliminar esta foto de este dispositivo?')){state.photos.splice(+id,1);await persist();render()}}else if(a==='export'){download('sealgym-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2),'application/json')}else if(a==='persistent'){let ok=await navigator.storage?.persist?.();toast(ok?'Almacenamiento persistente concedido.':'El navegador decide la persistencia. Conserva una copia JSON.')}else if(a==='reset'){if(confirm('¿Borrar de este navegador todo el perfil, sesiones, fotos y menús? Esta acción no se puede deshacer.')){state=blank();await persist();render()}}}catch(e){console.error(e);toast(e.message||'No se ha podido completar la acción.')}});
document.addEventListener('submit',async ev=>{ev.preventDefault();const f=ev.target,d=new FormData(f);try{if(f.id==='setform'){if(state.active.timer)return;state.active=recordSet(state.active,{weight:+d.get('weight'),reps:+d.get('reps'),rir:d.get('rir')===''?null:+d.get('rir'),technique:d.has('technique')});await persist();render()}else if(f.id==='profile'){for(const [k,v]of d)state.profile[k]=['age','height','weight','waist','time','days'].includes(k)?(v===''?null:+v):v;state.profile.medical=d.has('medical');state.profile.tolerance=d.has('tolerance');await persist();render();toast('Perfil guardado. Los cambios se aplican a la próxima sesión.')}else if(f.id==='scheduleform'){state.schedule=Array.from({length:5},(_,i)=>d.get('t'+i));state.reminders=d.has('enabled');await persist();$('#dialog').close();render();toast('Horarios guardados.')}else if(f.id==='portionsform'){let m=meals()[+f.dataset.id];m.items=m.items.map(([id])=>[id,+d.get(id)]);state.overrides[day+':'+f.dataset.id]=m;await persist();$('#dialog').close();render()}else if(f.id==='measureform'){if(!d.get('weight')&&!d.get('waist'))throw Error('Introduce al menos una medida.');state.measurements.push({date:d.get('date'),weight:d.get('weight')?+d.get('weight'):null,waist:d.get('waist')?+d.get('waist'):null});state.measurements.sort((a,b)=>a.date.localeCompare(b.date));await persist();$('#dialog').close();render()}}catch(e){toast(e.message)}});
document.addEventListener('change',async ev=>{let t=ev.target;try{if(t.id==='deload'){deload=t.checked;render()}else if(t.id==='filter'){filter=t.value;render()}else if(t.id==='chartExercise'){state.chartExercise=t.value;await persist();render()}else if(t.classList.contains('excluded')){state.profile.excluded=Array.from(document.querySelectorAll('.excluded:checked')).map(e=>e.value);await persist()}else if(t.classList.contains('equipment')){state.profile.material=Array.from(document.querySelectorAll('.equipment:checked')).map(e=>e.value);await persist()}else if(t.id==='import'&&t.files[0]){if(t.files[0].size>30*1024*1024)throw Error('Copia demasiado grande (máximo 30 MB).');let x=validState(JSON.parse(await t.files[0].text()));if(confirm('La importación reemplazará los datos actuales. ¿Continuar?')){state=x;await persist();render();toast('Copia recuperada.')}}else if(t.id==='photo'&&t.files[0]){let file=t.files[0];if(!/^image\//.test(file.type)||file.size>15*1024*1024)throw Error('Elige una imagen de menos de 15 MB.');let u=URL.createObjectURL(file),im=new Image();im.onload=async()=>{let c=document.createElement('canvas'),ratio=Math.min(1,1000/im.width);c.width=im.width*ratio;c.height=im.height*ratio;c.getContext('2d').drawImage(im,0,0,c.width,c.height);state.photos.push({date:new Date().toLocaleDateString('es-ES'),data:c.toDataURL('image/jpeg',.8)});URL.revokeObjectURL(u);await persist();render()};im.onerror=()=>{URL.revokeObjectURL(u);toast('Formato de imagen no compatible. Prueba JPEG o PNG.')};im.src=u;}}catch(e){toast(e.message)}});
document.addEventListener('input',ev=>{if(ev.target.id==='search'){query=ev.target.value;const pos=ev.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick()});window.addEventListener('online',()=>render());window.addEventListener('offline',()=>render());
try{db=await openDB();state=await readDB(db);state.profile.excluded||=[];render();setInterval(tick,500);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('Modo offline no disponible en este navegador.'));}catch(e){$('#app').innerHTML='<main class="content"><h1>No se pudo abrir el almacenamiento.</h1><p>Abre SealGym en Safari o Chrome con el almacenamiento del sitio permitido. No borres tus datos si tienes un historial sin exportar.</p></main>';console.error(e)}
